// Manual interpretation notes from north-up Amap satellite views.
// Row runs describe observed repeated roof bands; individual property divisions,
// facades and levels remain estimates, never cadastral or measured geometry.
export const regionalSurveyNotes={frames:[],roofs:[],runs:[],ground:[],lanes:[]};
function regionalFrame(id,lng,lat,zoom=16){regionalSurveyNotes.frames.push({id,center:[lng,lat],zoom,checked:'2026-11-26',imageryDate:null,url:`https://www.amap.com/ssr/embed/view?lng=${lng}&lat=${lat}&zoom=${zoom}&maptype=satellite&platform=pc`});}
function regionalRun(frame,u,v,w,d,du,dv,count,levels=1,kind='lowrise',roof='#858478',angle=.15){regionalSurveyNotes.runs.push({frame,u,v,w,d,du,dv,count,levels,kind,roofColor:roof,angle,footprintMethod:'observed-row-pattern-estimate'});}
function regionalRoofs(frame,levels,kind,roof,rows){rows.forEach(([u,v,w,d,angle=.15])=>regionalSurveyNotes.roofs.push({frame,u,v,w,d,levels,kind,roofColor:roof,angle,footprintMethod:'manual-roof-interpretation'}));}
function regionalGround(frame,kind,points){regionalSurveyNotes.ground.push({frame,kind,points});}
function regionalLane(frame,width,points){regionalSurveyNotes.lanes.push({frame,width,points});}

